<template>
  <section ref="comparisonRoot" class="device-comparison">
    <div class="comparison-heading">
      <div class="comparison-modes" aria-label="选择健康监控视图"><button v-for="mode in modes" :key="mode.id" type="button" :class="{ active: activeMode === mode.id }" :aria-pressed="activeMode === mode.id" @click="activeMode = mode.id">{{ mode.label }}</button></div>
      <div class="month-selectors"><label>查看月份<FormSelect v-model="viewMonth" :options="monitoringMonths" placeholder="" aria-label="查看月份"/></label><label>对比月份<FormSelect v-model="compareMonth" :options="monitoringMonths" placeholder="" aria-label="对比月份"/></label></div>
    </div>
    <p class="comparison-period">按月统计运行变化 · 主值为月均，变化值相对 {{ monthLabel(compareMonth) }}</p>
    <template v-if="activeMode === 'shared'">
      <div class="component-intro"><h4>共用部件</h4><p>查看跨缸供给与回流的月度变化，再沿链路进入各缸。</p></div>
      <div class="shared-system-grid"><button v-for="system in sharedSystems" :key="system.id" type="button" :class="{ active: selectedSharedSystem === system.id }" :aria-pressed="selectedSharedSystem === system.id" @click="selectSharedPart(system.id)"><EnginePartIcon :kind="system.id" :size="64"/><span class="shared-card-copy"><strong>{{ system.name }}</strong><small>{{ system.sensorIds.length }} 项关联测点</small></span></button></div>
    </template>
    <template v-else-if="activeMode === 'cylinders'">
      <div class="topology-intro"><div><strong>RT-flex50 · 本船六缸配置</strong><span>同月同类测量横向对比，点击数值查看部件链路</span></div><span>6 个气缸 · 6 类关联部件</span></div>
      <div class="six-cylinder-strip" aria-label="选择气缸"><button v-for="number in cylinderNumbers" :key="number" type="button" :class="{ active: selectedCylinder === number }" :aria-pressed="selectedCylinder === number" @click="selectedCylinder = number"><EnginePartIcon kind="cylinder" :size="56"/><strong>{{ number }} 号缸</strong></button></div>
      <div class="cylinder-matrix-scroll"><table class="cylinder-matrix"><caption>月均值 / 较对比月变化。变化用于观察趋势，结合工况与关联记录判断。</caption><thead><tr><th>测量 / 关联部件</th><th v-for="number in cylinderNumbers" :key="number" :class="{ selected: selectedCylinder === number }">{{ number }} 号缸</th></tr></thead><tbody><tr v-for="topic in cylinderMatrix" :key="topic.id"><th>{{ topic.name }}<small>{{ topic.unit || '指令与反馈' }}</small></th><td v-for="cell in topic.cells" :key="cell.id" :class="{ selected: cell.number === selectedCylinder, focused: cell.number === selectedCylinder && topic.id === selectedCylinderTopic }"><button type="button" :class="{ available: monthlyFor(cell.sensor).available }" :aria-label="`查看 ${cell.number} 号缸${topic.name}`" :aria-pressed="cell.number === selectedCylinder && topic.id === selectedCylinderTopic" @click="selectCylinderCell(cell.number, topic.id)"><strong>{{ meanLabel(monthlyFor(cell.sensor)) }}</strong><span>{{ deltaLabel(monthlyFor(cell.sensor)) }}</span></button></td></tr></tbody></table></div>
    </template>
    <template v-else-if="activeMode === 'generators'">
      <div class="component-intro"><h4>机组月度对比</h4><p>比较相同月份的运行指标，点选指标查看多月趋势。</p></div>
      <div class="generator-table-scroll"><table class="generator-table"><thead><tr><th>机组</th><th>负荷月均</th><th>转速月均</th><th>排温月均</th><th>冷却水出口月均</th><th>设备入口</th></tr></thead><tbody><tr v-for="generator in generators" :key="generator.id"><th>{{ generator.name }}</th><td v-for="metric in generator.metrics" :key="metric.key"><button type="button" class="generator-metric" :class="{ active: focusedSensor?.id === metric.sensor?.id }" :aria-label="`查看${generator.name}${metric.label}月度趋势`" @click="selectAuxMetric(metric.sensor)"><strong>{{ meanLabel(metric.stats) }} <small>{{ metric.stats.available ? metric.stats.unit : '' }}</small></strong><span>{{ deltaLabel(metric.stats) }}</span></button></td><td><button type="button" class="p2-link-button" :aria-label="`查看${generator.name}设备态势`" @click="$emit('select-device', generator.id)">查看设备 →</button></td></tr></tbody></table></div>
      <p class="comparison-note">负荷、运行时间与备用安排会影响月度统计，跨机组差异需结合运行记录理解。</p>
    </template>
    <section v-if="focusedPart" ref="detailPanel" class="part-detail" aria-label="部件月度趋势与关联">
      <div class="part-detail-heading"><EnginePartIcon :kind="focusedPart.kind" :size="56"/><div><span class="p2-eyebrow">{{ isMain ? '链路与关联' : '月度趋势' }}</span><h4>{{ focusedPart.title }}</h4><p>{{ focusedPart.description }}</p></div></div>
      <div v-if="focusedRoutes.length" class="linkage-routes" aria-label="部件链路"><div v-for="(route, routeIndex) in focusedRoutes" :key="routeIndex" class="linkage-route"><span v-for="(node, index) in route" :key="`${routeIndex}-${index}`" class="linkage-step"><span v-if="index" class="linkage-arrow" aria-hidden="true">→</span><button v-if="node.sharedId" type="button" class="linkage-node shared" @click="selectSharedSystem(node.sharedId)"><small>共用</small>{{ node.label }}<b>↗</b></button><span v-else class="linkage-node" :class="{ local: node.local }"><small v-if="node.local">{{ selectedCylinder }} 号缸</small>{{ node.label }}</span></span></div></div>
      <div v-if="activeMode === 'shared' && currentSharedSystem?.readings.length" class="monthly-metric-tabs" aria-label="选择月度指标"><button v-for="sensor in currentSharedSystem.readings" :key="sensor.id" type="button" :class="{ active: focusedSensor?.id === sensor.id }" :aria-pressed="focusedSensor?.id === sensor.id" @click="selectedSharedMetric = sensor.id"><span>{{ sensor.nameCn }}</span><strong>{{ meanLabel(monthlyFor(sensor)) }} <small>{{ monthlyFor(sensor).available ? monthlyFor(sensor).unit : '' }}</small></strong><small>{{ deltaLabel(monthlyFor(sensor)) }}</small></button></div>
      <div class="monthly-summary"><div><span>{{ monthLabel(viewMonth) }} · 月均</span><strong>{{ meanLabel(focusedStats) }} <small>{{ focusedStats.available ? focusedStats.unit : '' }}</small></strong></div><div><span>较 {{ monthLabel(compareMonth) }}</span><strong class="monthly-change">{{ deltaLabel(focusedStats) }}</strong></div><div><span>月内范围</span><strong class="monthly-range">{{ rangeLabel(focusedStats) }}</strong></div></div>
      <div class="monthly-chart"><div class="comparison-subheading"><h5>{{ focusedSensor?.nameCn || '对应指标' }} · 月均趋势</h5><span>{{ focusedStats.unit }}</span></div><template v-if="chartModel.points.length"><svg viewBox="0 0 720 165" role="img" :aria-label="`${focusedSensor?.nameCn || '指标'}最近六个月月均趋势`"><line v-for="y in [20,75,130]" :key="y" x1="48" :y1="y" x2="704" :y2="y" class="chart-grid"/><text x="0" y="24">{{ chartModel.top }}</text><text x="0" y="134">{{ chartModel.bottom }}</text><polyline v-for="(segment,index) in chartModel.segments" :key="index" :points="segment" class="chart-line"/><circle v-for="point in chartModel.points" :key="point.month" :cx="point.x" :cy="point.y" :r="point.month === viewMonth ? 5 : 3" :class="{ selected: point.month === viewMonth }"><title>{{ monthLabel(point.month) }}：{{ formatNumber(point.mean, focusedStats.precision) }} {{ focusedStats.unit }}</title></circle><text v-for="point in chartModel.labels" :key="point.month" :x="point.x" y="155" text-anchor="middle">{{ point.month.slice(5) }}月</text></svg></template><div v-else class="comparison-empty">暂无月度统计。</div></div>
      <div v-if="focusedSensor" class="data-link"><button type="button" class="p2-link-button" @click="$emit('select-sensor', focusedSensor)">查看传感器数据 →</button></div>
      <div v-if="activeMode === 'shared'" class="shared-cylinder-navigation"><div class="comparison-subheading"><h5>逐缸关联</h5><div class="related-topic-switch"><button v-for="topic in relatedCylinderTopics" :key="topic.id" type="button" :class="{ active: linkedCylinderTopic === topic.id }" :aria-pressed="linkedCylinderTopic === topic.id" @click="selectedLinkedTopic = topic.id">{{ topic.name }}</button></div></div><div class="linked-cylinder-buttons"><button v-for="number in cylinderNumbers" :key="number" type="button" @click="openLinkedCylinder(number)">{{ number }} 号缸 <span>→</span></button></div></div>
      <div v-else-if="activeMode === 'cylinders'" class="supply-links"><span>关联共用部件</span><button v-for="supply in selectedCylinderDetail?.supplies || []" :key="supply.id" type="button" @click="selectSharedSystem(supply.id)">{{ supply.shortName }} ↗</button></div>
      <div v-if="focusedIssues.length" class="part-linked-issues"><span>关联事项</span><button v-for="item in focusedIssues" :key="item.id" type="button" @click="$emit('open-item', item.id)">{{ item.title }} · {{ item.state }} →</button><small>按来源时间与实际处理记录查阅。</small></div>
    </section>
    <details v-if="isMain" class="topology-sources"><summary>结构与测点依据</summary><p v-for="source in rtFlex50Sources" :key="source.title"><strong>{{ source.title }}</strong>：{{ source.scope }}</p></details>
  </section>
</template>

<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import { useSensorStore } from '@/stores/sensorStore'
import { usePhase2DemoStore } from '@/stores/phase2DemoStore'
import { workbenchIssues } from '@/mock/captainWorkbench'
import { parentIssueId } from '@/mock/issueRelationships'
import { cylinderNumbers, cylinderTopics, buildCylinderMatrix, cylinderDetail, sharedSystems, sharedSystemDetail, rtFlex50Sources } from '@/mock/deviceComparisonTopology'
import { monitoringMonths, getMonthlySensorStats } from '@/mock/monthlyHealthMonitoring'
import EnginePartIcon from '@/components/EnginePartIcon.vue'
import FormSelect from '@/components/forms/FormSelect.vue'
const props = defineProps({ deviceId: { type: String, required: true } })
defineEmits(['open-data', 'select-sensor', 'select-device', 'open-item'])
const sensorStore = useSensorStore(), store = usePhase2DemoStore()
const comparisonRoot = ref(null), detailPanel = ref(null)
const activeMode = ref('shared'), selectedCylinder = ref(2), selectedCylinderTopic = ref('exhaust')
const selectedSharedSystem = ref('fuel'), selectedSharedMetric = ref(''), selectedLinkedTopic = ref('icu'), selectedAuxMetric = ref('')
const viewMonth = ref(monitoringMonths.at(-1)?.value || ''), compareMonth = ref(monitoringMonths.at(-2)?.value || '')
const isMain = computed(() => props.deviceId === 'main-engine-1')
const modes = computed(() => isMain.value ? [{ id: 'shared', label: '共用部件' }, { id: 'cylinders', label: '多缸对比' }] : [{ id: 'generators', label: '机组对比' }])
const deviceReadings = computed(() => sensorStore.allSensors.filter(sensor => sensor.deviceId === props.deviceId))
const deviceIssues = computed(() => workbenchIssues(store).filter(item => item.deviceId === props.deviceId))
const cylinderMatrix = computed(() => buildCylinderMatrix(deviceReadings.value))
const selectedCylinderDetail = computed(() => cylinderDetail(selectedCylinder.value, selectedCylinderTopic.value, deviceReadings.value))
const currentSharedSystem = computed(() => sharedSystemDetail(selectedSharedSystem.value, deviceReadings.value))
const relatedCylinderTopics = computed(() => cylinderTopics.filter(topic => topic.shared.includes(selectedSharedSystem.value)))
const linkedCylinderTopic = computed(() => relatedCylinderTopics.value.some(topic => topic.id === selectedLinkedTopic.value) ? selectedLinkedTopic.value : relatedCylinderTopics.value[0]?.id)
const noStats = { available: false, mean: null, min: null, max: null, delta: null, unit: '', precision: 1, series: [] }
const monthlyStats = computed(() => Object.fromEntries(sensorStore.allSensors.map(sensor => [sensor.id, getMonthlySensorStats(sensor, viewMonth.value, compareMonth.value) || noStats])))
function monthlyFor(sensor) { return sensor ? monthlyStats.value[sensor.id] || noStats : noStats }
const generators = computed(() => [1,2,3].map(number => ({id:`aux-engine-${number}`,name:`${number}号辅机`,metrics:[['load','负荷'],['rpm','转速'],['exhaust','排气温度'],['water','冷却水出口']].map(([key,label])=>{const sensor=sensorStore.allSensors.find(item=>item.id===`aux-${number}-${key}`);return{key,label,sensor,stats:monthlyFor(sensor)}})})))
const focusedSensor = computed(() => {if(activeMode.value==='cylinders')return selectedCylinderDetail.value?.sensor;if(activeMode.value==='shared')return currentSharedSystem.value?.readings.find(sensor=>sensor.id===selectedSharedMetric.value)||currentSharedSystem.value?.readings[0];const preferred=selectedAuxMetric.value||`aux-${props.deviceId.match(/aux-engine-(\d)/)?.[1]||1}-exhaust`;return sensorStore.allSensors.find(sensor=>sensor.id===preferred)})
const focusedStats = computed(() => monthlyFor(focusedSensor.value))
const focusedPart = computed(() => {if(activeMode.value==='cylinders'&&selectedCylinderDetail.value)return{title:`${selectedCylinder.value} 号缸 · ${selectedCylinderDetail.value.name}`,kind:({coolant:'cooling',piston:'lubrication'})[selectedCylinderTopic.value]||selectedCylinderTopic.value,description:selectedCylinderDetail.value.component};if(activeMode.value==='shared'&&currentSharedSystem.value)return{title:currentSharedSystem.value.name,kind:currentSharedSystem.value.id,description:currentSharedSystem.value.relationship};return focusedSensor.value?{title:focusedSensor.value.nameCn,kind:'cylinder',description:'结合运行月份、负荷和备用安排查看变化。'}:null})
const focusedIssues = computed(() => {const ids=activeMode.value==='cylinders'?selectedCylinderDetail.value?.issueIds:activeMode.value==='shared'?currentSharedSystem.value?.issueIds:[];const parents=new Set((ids||[]).map(parentIssueId));return deviceIssues.value.filter(item=>parents.has(item.id))})
const focusedRoutes = computed(() => {
 if(!isMain.value)return[]
 if(activeMode.value==='shared')return[(currentSharedSystem.value?.path||'').split('→').map(label=>({label:label.trim()})).filter(node=>node.label)]
 const local=label=>({label,local:true}),common=(label,sharedId)=>({label,sharedId}),part=label=>({label})
 return {
  exhaust:[[local('燃烧室'),local('排气阀'),common('排气汇流','exhaust'),common('增压器','exhaust')]],
  scavenge:[[common('增压器','scavenge'),part('空冷器'),part('水分离器'),common('扫气接收器','scavenge'),local('扫气口')]],
  coolant:[[common('冷却水分配管','cooling'),local('气缸套'),local('气缸盖'),local('排气阀壳'),common('出口回流','cooling')]],
  piston:[[common('轴承油供给','lubrication'),local('伸缩管'),local('活塞冷却通道'),common('回油','lubrication')]],
  icu:[[common('燃油轨','fuel'),local('ICU'),local('喷油器')],[common('伺服油轨','servo'),local('ICU 执行机构')],[local('FCM-20 控制'),local('ICU')]],
  vcu:[[common('伺服油轨','servo'),local('VCU'),local('排气阀液压开启')],[common('控制空气','control-air'),local('空气弹簧'),local('排气阀关闭')]],
 }[selectedCylinderTopic.value]||[]
})
const chartModel = computed(() => {
 const series=focusedStats.value.series||[],values=series.map(item=>numberValue(item.mean)).filter(value=>value!==null)
 if(!values.length)return{points:[],segments:[],labels:[],top:'',bottom:''}
 const low=Math.min(...values),high=Math.max(...values),padding=Math.max((high-low)*.15,Math.abs(high)*.002,.01),bottom=low-padding,top=high+padding
 const labels=series.map((item,index)=>({month:item.month,x:48+index*656/Math.max(series.length-1,1)})),points=[],segments=[];let segment=[]
 series.forEach((item,index)=>{const mean=numberValue(item.mean);if(mean===null){if(segment.length)segments.push(segment.join(' '));segment=[];return}const point={month:item.month,mean,x:labels[index].x,y:130-(mean-bottom)/(top-bottom)*110};points.push(point);segment.push(`${point.x},${point.y}`)})
 if(segment.length)segments.push(segment.join(' '))
 return{points,segments,labels,top:formatNumber(top,focusedStats.value.precision),bottom:formatNumber(bottom,focusedStats.value.precision)}
})
function numberValue(value){if(!['number','string'].includes(typeof value)||(typeof value==='string'&&!value.trim()))return null;const number=Number(value);return Number.isFinite(number)?number:null}
function formatNumber(value,precision=1){const number=numberValue(value);return number===null?'—':number.toFixed(Math.min(3,Math.max(0,precision??1)))}
function meanLabel(stats){return stats.available?formatNumber(stats.mean,stats.precision):'—'}
function deltaLabel(stats){const delta=numberValue(stats.delta);if(!stats.available||delta===null)return'暂无对比';const rounded=Number(formatNumber(delta,stats.precision));return`${rounded>0?'+':''}${formatNumber(rounded,stats.precision)}${stats.unit?' '+stats.unit:''}`}
function rangeLabel(stats){return stats.available?`${formatNumber(stats.min,stats.precision)} – ${formatNumber(stats.max,stats.precision)} ${stats.unit}`:'—'}
function monthLabel(month){return monitoringMonths.find(item=>item.value===month)?.label||month}
function selectSharedPart(id){selectedSharedSystem.value=id;selectedSharedMetric.value=''}
async function selectCylinderCell(number,topicId){selectedCylinder.value=number;selectedCylinderTopic.value=topicId;await nextTick();detailPanel.value?.scrollIntoView({block:'nearest'})}
async function selectSharedSystem(id){selectSharedPart(id);activeMode.value='shared';await nextTick();comparisonRoot.value?.scrollIntoView({block:'start'})}
async function openLinkedCylinder(number){activeMode.value='cylinders';await selectCylinderCell(number,linkedCylinderTopic.value||'exhaust')}
async function selectAuxMetric(sensor){if(!sensor)return;selectedAuxMetric.value=sensor.id;await nextTick();detailPanel.value?.scrollIntoView({block:'nearest'})}
watch(()=>props.deviceId,()=>{activeMode.value=isMain.value?'shared':'generators';selectedAuxMetric.value=''}, {immediate:true})
</script>
<style scoped>
